function promiseAll(values) {
  return new Promise((resolve, reject) => {
    const results = [];
    values.forEach((value) => {
      Promise.resolve(value).then((result) => {
        results.push(result);
        if (results.length === values.length) {
          resolve(results);
        }
      }, reject);
    });
  });
}

